  };
  live: {
    latitude: number;
    longitude: number;
    altitude: number;
    direction: number;
    speed_horizontal: number;
  } | null;
  departure: {
    airport: string;
    timezone: string;
    latitude?: number | null;
    longitude?: number | null;
  };
  arrival: {
    airport: string;
    timezone: string;
    latitude?: number | null;
    longitude?: number | null;
  };
}

