export async function fetchLiveFlights(limit: number = 5): Promise<FlightData[]> {
  // Always use mock data while developing/testing features
  const USE_MOCK = true;

  if (USE_MOCK) {
    console.log("Using Mock AviationStack Data");
    // Return a sliced version of mock flights depending on limit
    return MOCK_FLIGHTS.slice(0, limit);
  }

  const apiKey = process.env.AVIATIONSTACK_API_KEY;
  if (!apiKey) {
    console.error("AVIATIONSTACK_API_KEY is not defined");
    return MOCK_FLIGHTS; // Fallback to mock if no API key
  }

  try {
    const response = await fetch(`https://api.aviationstack.com/v1/flights?access_key=${apiKey}&flight_status=active&limit=${limit}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch flights: ${response.statusText}`);
    }

    const json = await response.json();
    return json.data || [];
  } catch (error) {
    console.error("Error fetching flights:", error);
    return MOCK_FLIGHTS; // Fallback to mock on error
  }
}

import { NextResponse } from 'next/server';
import { fetchLiveFlights } from '@/lib/api/aviationstack';

export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    const flights = await fetchLiveFlights(5);
    return NextResponse.json(flights);
  } catch (error) {
    console.error('Error in flights API route:', error);
    return NextResponse.json({ error: 'Failed to fetch flights' }, { status: 500 });
  }
}

import type { Flight } from "./types";

// Persist the last good feed in the browser so a page reload shows planes
// instantly — before (and even instead of) a slow/empty/rate-limited refresh.
// This decouples "is there something on the map" from any server/CDN caching.

const KEY = "aerostack:flights:v1";
// Don't rehydrate a feed older than this; positions would be too stale to be
// useful (dead reckoning is clamped well below this anyway).
const MAX_AGE_MS = 30 * 60_000;

export function loadCachedFlights(): Flight[] | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { t: number; data: Flight[] };
    if (!Array.isArray(parsed.data) || Date.now() - parsed.t > MAX_AGE_MS) return null;
    return parsed.data;
  } catch {
    return null;
  }
}

export function saveCachedFlights(data: Flight[]): void {
  if (typeof window === "undefined" || data.length === 0) return;
  try {
    window.localStorage.setItem(KEY, JSON.stringify({ t: Date.now(), data }));
  } catch {
    // Quota or serialization failure — non-fatal, just skip persisting.
  }
}

// Lightweight in-memory rate limiter (fixed-window counter), used to protect
// the Aviationstack quota from a single client generating many distinct,
// cache-busting queries. The shared Next.js Data Cache already coalesces
// identical requests across users; this adds a per-client ceiling on top.
//
// Caveat: state lives in module memory, so it is per-instance and resets on
// cold start. On a multi-instance / serverless deployment it is best-effort,
// not a global guarantee — for hard global limits, back it with a shared store
// (Upstash Redis, Vercel KV, etc.). It is still effective against a single
// abusive client hitting one warm instance.

type Window = { count: number; resetAt: number };

const buckets = new Map<string, Window>();

// Evict expired windows opportunistically so the map can't grow without bound
// under a stream of unique keys.
function sweep(now: number) {
  if (buckets.size < 5000) return;
  for (const [key, w] of buckets) {
    if (w.resetAt <= now) buckets.delete(key);
  }
}

export type RateLimitResult = {
  ok: boolean;
  remaining: number;
  /** Seconds until the window resets (for a Retry-After header). */
  retryAfter: number;
};

export function rateLimit(
  key: string,
  { limit, windowMs }: { limit: number; windowMs: number }
): RateLimitResult {
  const now = Date.now();
  sweep(now);

  const existing = buckets.get(key);
  if (!existing || existing.resetAt <= now) {
    buckets.set(key, { count: 1, resetAt: now + windowMs });
    return { ok: true, remaining: limit - 1, retryAfter: 0 };
  }

  existing.count += 1;
  const remaining = Math.max(0, limit - existing.count);
  const retryAfter = Math.ceil((existing.resetAt - now) / 1000);
  return { ok: existing.count <= limit, remaining, retryAfter };
}

// Best-effort client identity from common proxy headers. Falls back to a shared
// bucket when no IP is available (e.g. local dev), which is acceptable since the
// limiter is a safety net rather than an auth boundary.
export function clientKey(request: Request): string {
  const fwd = request.headers.get("x-forwarded-for");
  if (fwd) return fwd.split(",")[0].trim();
  return request.headers.get("x-real-ip") || "anonymous";
}

